mapper.select:
select THIRD_USER_ID, CARD_ID, CARD_TYPE, CHANNEL, THIRD_PAY_ID, REQ_CONTRACT_NO, STATUS, CREATE_TMS, UPDATE_TMS
from APP_USER_PAY_CHANNEL
where THIRD_USER_ID = #{thirdUserId,jdbcType=VARCHAR}
  and CARD_TYPE = #{cardType,jdbcType=VARCHAR}
  and CHANNEL = #{channel,jdbcType=VARCHAR}

mapper.delete:
delete from APP_USER_PAY_CHANNEL
where THIRD_USER_ID = #{thirdUserId,jdbcType=VARCHAR}
  and CARD_TYPE = #{cardType,jdbcType=VARCHAR}
  and CHANNEL = #{channel,jdbcType=VARCHAR}
